# Names for tests/nrom128.asm when it is recompiled from its assembled image
# (tests/check_fixtures.py). The inline tables after the two dispatchers'
# calls must be listed; the other routines get generated names.
io $2003 oam_address
routine $c000 boot
table $c04a handlers 4                   ; addresses after the call to choose
routine $c054 choose                     ; jump through the address table after the call
table $c06e return_handlers 4            ; return addresses (target - 1)
routine $c078 return_dispatch            ; return through the table after the call
routine $c093 tick
table $fffa vectors 6
